import {professionLabel,professionProfile,bindProfession} from './profession.js';
import {notificationsHTML,bindNotifications} from './notifications.js';
import {sendObservation} from './offline.js';
import {FEATURES as COMMUNITY_FEATURES} from './community-features.js';
import {fotoDataURL} from './photo-tools.js';
import {reportHaptic,createFeedFeedback} from './ui-feedback.js';
import {esc,weatherName,valueText,weatherKind} from './weather-tools.js';
export const SKY_LEVELS=[['Asciutto','Niente pioggia'],['Qualche goccia','Si sente appena'],['Pioviggina','Senza ombrello si arriva'],['Piove','Ombrello necessario'],['Diluvio','Meglio restare']];
export const skyDistance=(a,b)=>{const d=Math.PI/180,p=(b.latitude-a.latitude)*d,l=(b.longitude-a.longitude)*d;return 12742*Math.asin(Math.min(1,Math.sqrt(Math.sin(p/2)**2+Math.cos(a.latitude*d)*Math.cos(b.latitude*d)*Math.sin(l/2)**2)))};
export function selectNearby(reports,place,now=Date.now()){
 const valid=p=>Number.isFinite(p?.latitude)&&Number.isFinite(p?.longitude)&&Math.abs(p.latitude)<=90&&Math.abs(p.longitude)<=180;
 if(!valid(place))return {rows:[],radius:null,unavailable:true};
 const sorted=(reports||[]).filter(r=>valid(r)&&Number.isFinite(r.created)&&r.created<=now&&r.created>now-7200000&&Number.isFinite(r.expires)&&r.expires>now).map(r=>({...r,distanceKm:skyDistance(place,r)})).filter(r=>r.distanceKm<=150).sort((a,b)=>a.distanceKm-b.distanceKm||b.created-a.created);
 const radius=[5,15,50,150].find(km=>sorted.some(r=>r.distanceKm<=km))??150;
 return {rows:sorted.filter(r=>r.distanceKm<=radius),radius,unavailable:false};
}
export function reportLife(report,now=Date.now()){return Math.max(0,Math.min(1,(report.expires-now)/7200000))}
export function agreeingPeople(own,reports,now=Date.now()){
 const latest=new Map();for(const row of reports||[]){if(row.created>now||row.created<Math.max(own.created,now-900000)||row.expires<=now||row.author===own.author||skyDistance(own,row)>3)continue;const old=latest.get(row.author);if(!old||old.created<row.created)latest.set(row.author,row)}
 return [...latest.values()].filter(row=>row.kind===own.kind&&(own.phenomenon||row.phenomenon||Math.abs(row.level-own.level)<=1)).length;
}
const distanceText=km=>km<1?'meno di 1 km':Math.round(km)+' km';
const QUICK={'Pioggia':'☂','Grandine':'◇','Neve':'❄','Vento':'≋','Allagamento':'≈','Cielo sereno':'☀'};
const reportLabel=r=>r.phenomenon||SKY_LEVELS[r.level]?.[0]||r.kind;
const $=s=>document.querySelector(s),time=t=>new Date(t).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});
export function createSkyCommunity(ctx){
 const sends=new Map(),confirming=new Set();let displayName='',feedMotion=null,confirmationPosition=null,confirmationPositionAt=0,feedbackText='',feedbackReport='';
 function renderFeed(){const host=$('#sky-feed');if(!host)return;feedMotion??=createFeedFeedback();feedMotion.render(host,content());bindControls()}
 try{displayName=localStorage.getItem('meteosocial-sky-name')||''}catch{}
 if(!displayName){displayName='Voce del cielo '+(crypto.getRandomValues(new Uint32Array(1))[0]%10000);try{localStorage.setItem('meteosocial-sky-name',displayName)}catch{}}
 function profileHTML(){return professionProfile()+notificationsHTML()+`<section class="card"><h2>Il nome delle tue segnalazioni</h2><form id="sky-name-form"><label>Nome pubblico<input id="sky-name" minlength="2" maxlength="40" required value="${esc(displayName)}"></label><button type="submit">Salva nome</button><p role="status" id="sky-name-status"></p></form></section>`}
 function bindProfile(){bindProfession({api:ctx.api,changed:()=>{lastLoad=0;data=null;}});bindNotifications();const f=$('#sky-name-form');if(f)f.onsubmit=e=>{e.preventDefault();const n=$('#sky-name').value.trim();if(n.length<2)return;displayName=n;try{localStorage.setItem('meteosocial-sky-name',n);$('#sky-name-status').textContent='Nome salvato per le prossime segnalazioni.'}catch{$('#sky-name-status').textContent='Nome valido per questa visita: salvataggio non disponibile.'}}}
 function grid(){return `<section class="quick-report-panel"><h2>Segnala adesso</h2><p>Con un tocco pubblichi ciò che osservi a ${esc(ctx.get().place.name)}, nella zona approssimata, per 2 ore.</p><div class="quick-report-grid">${Object.entries(QUICK).map(([kind,icon])=>`<button type="button" data-sky-quick="${kind}"><span aria-hidden="true">${icon}</span><span>${kind}</span></button>`).join('')}</div></section>`}
 function outbox(){return [...sends.values()].map(d=>`<article class="sky-report-row" data-report-key="${esc(d.id)}" role="status"><strong>${esc(d.phenomenon)}</strong><p>${esc(d.name)} · ${esc(d.city)}</p><p>${d.busy?(d.message||'Invio in corso…'):d.message||'Non ancora inviata.'}</p>${!d.busy?`<button type="button" data-sky-send="${d.id}">${d.auth?'Accedi e riprova':'Riprova'}</button><button type="button" data-sky-cancel="${d.id}">Annulla tentativo</button>`:''}</article>`).join('')}
 function bindQuick(){document.querySelectorAll('[data-sky-quick]').forEach(b=>b.onclick=e=>quick(b.dataset.skyQuick,e.isTrusted));document.querySelectorAll('[data-sky-send]').forEach(b=>b.onclick=e=>{const d=sends.get(b.dataset.skySend);if(d?.auth)ctx.login();else if(d)sendQuick(d,e.isTrusted)});document.querySelectorAll('[data-sky-cancel]').forEach(b=>b.onclick=()=>{sends.delete(b.dataset.skyCancel);paint()})}
 function quick(phenomenon,userGesture=false){if([...sends.values()].some(d=>d.busy))return;const p=ctx.get().place,d={id:crypto.randomUUID(),name:displayName,phenomenon,latitude:p.latitude,longitude:p.longitude,city:p.name,consent:true,level:0,options:[]};sends.set(d.id,d);return sendQuick(d,userGesture)}
 async function sendQuick(d,userGesture=false){if(d.busy)return;d.busy=true;d.auth=false;d.message='';paint();try{let result;for(let attempt=0;attempt<2;attempt++){try{result=await sendObservation({observedAt:d.observedAt||(d.observedAt=Date.now()),id:d.id,name:d.name,phenomenon:d.phenomenon,latitude:d.latitude,longitude:d.longitude,city:d.city,consent:true,level:0,options:[]});break}catch(e){if(attempt||e.status&&e.status<500||navigator.onLine===false)throw e;d.message='Riprovo…';paint();await new Promise(resolve=>setTimeout(resolve,700));}}sends.delete(d.id);if(result.queued){ctx.toast('Verrà inviata appena torni online.');return}data=data||{reports:[],stats:result.stats,asOf:Date.now()};data.reports=[result.report,...data.reports.filter(r=>r.id!==d.id)];if(data.nearbyReports)data.nearbyReports=[result.report,...data.nearbyReports.filter(r=>r.id!==result.report.id)];data.stats=result.stats;data.asOf=Date.now();error='';feedbackAt=Date.now()+180000;feedbackReport=result.report.id;feedbackText='';paint();reportHaptic('success',userGesture);if(ctx.get().route==='mappa')ctx.world.celebrate(result.report);if(active())offerNote(result.report,result.firstInCity);else ctx.toast('Segnalazione pubblicata.')}catch(e){d.auth=e.status===401;d.message=d.auth?'La prima segnalazione non richiede un account. Per inviarne un’altra, accedi.':e.status&&e.status<500?e.message:'Non ancora inviata. Puoi riprovare senza creare duplicati.';reportHaptic('error',userGesture)}finally{d.busy=false;paint()}}
 function offerNote(report,firstInCity=false){ctx.modal('Fatto. Vuoi aggiungere una parola?',` ${firstInCity?`<p><strong>Sei la prima voce di ${esc(report.city)} nelle ultime 2 ore.</strong></p>`:''}<p>La segnalazione è già pubblicata. Il testo è facoltativo.</p><label>Che cosa osservi?<textarea id="sky-note" maxlength="300"></textarea></label><button type="button" id="sky-skip-note">Salta</button>`,async()=>{await ctx.api('sky/note',{id:report.id,note:$('#sky-note').value.trim()});lastLoad=0;await load(true);return true});$('#sky-skip-note').onclick=()=>$('#dialog').close()}
 let data=null,error='',loading=false,lastLoad=0,timer=0,zoneRun=0,pending=null,feedbackAt=0,posting=false,reportDraft=null;
 const active=()=>['mappa','community'].includes(ctx.get().route),placeKey=()=>`${ctx.get().place.latitude},${ctx.get().place.longitude}`,localSource=()=>data?.nearbyFor===placeKey()?data.nearbyReports:data?.reports,nearby=()=>selectNearby(localSource(),ctx.get().place),incomplete=()=>data?.nearbyFor===placeKey()?data.nearbyTruncated:data?.truncated,findReport=id=>localSource()?.find(r=>r.id===id)||data?.reports.find(r=>r.id===id);
 function invitation(){const {place,weather}=ctx.get(),c=weather?.current;return `<div class="sky-invitation"><p>${c?`${valueText(c.temperature_2m,'°')} · ${esc(weatherName(c.weather_code))}`:''}</p><h2>Com’è il cielo a ${esc(place.name)}?</h2><button type="button" class="sky-primary" data-sky-open>Racconta il tuo cielo</button><details class="info-disclosure"><summary aria-label="Segnalazioni della zona">i</summary><p>${incomplete()?'Non trovo segnalazioni entro 150 km nei dati caricati. Il risultato è parziale.':'Non risultano segnalazioni entro 150 km nelle ultime due ore.'}</p></details></div><div data-live-discovery></div>`}

 function canConfirm(r){return !r.own&&!r.confirmed&&r.visibility!=='only-you'&&r.expires>Date.now()&&confirmationPosition&&Date.now()-confirmationPositionAt<300000&&skyDistance(confirmationPosition,r)<=5}
 function card(r){const remaining=reportLife(r),minutes=Math.ceil(remaining*120);return `<article class="sky-report-row sky-lived-card" data-report-key="${esc(r.id)}" data-expires="${r.expires}" style="opacity:${.85+.15*remaining}"><button type="button" data-sky-zone="${esc(r.id)}"><span class="sky-dot sky-${esc(r.kind)}" aria-hidden="true"></span><span><strong>${esc(reportLabel(r))} · ${Math.max(0,Math.floor((Date.now()-r.created)/60000))} min fa</strong><span>${esc(r.name||'Una persona')}${professionLabel(r.mestiere)} · ${esc(r.city)} · ${time(r.created)}${Number.isFinite(r.distanceKm)?' · circa '+distanceText(r.distanceKm):''}${r.own?' · Tu':''}</span></span></button>${r.note?`<p>${esc(r.note)}</p>`:''}${r.photo?`<img loading="lazy" src="/api/sky/photo/${encodeURIComponent(r.id)}" alt="Il cielo raccontato a ${esc(r.city)}">`:''}<div class="sky-confirmation"><span>${r.confirmed?'Hai confermato · ':''}Confermato da ${r.confirms||0} ${(r.confirms||0)===1?'persona':'persone'}</span>${canConfirm(r)?`<button type="button" data-sky-confirm="${esc(r.id)}" ${confirming.has(r.id)?'disabled':''}>${confirming.has(r.id)?'Invio…':'✓ Confermo, anche da me'}</button>`:''}</div><progress class="sky-time-left" max="120" value="${remaining*120}" aria-label="Visibile ancora per ${minutes} minuti"></progress></article>`}
 function currentPosition(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('La posizione non è disponibile su questo dispositivo.'));navigator.geolocation.getCurrentPosition(p=>{if(!Number.isFinite(p.coords.accuracy)||p.coords.accuracy>2000)return reject(Error('La posizione non è abbastanza precisa. Riprova quando il dispositivo riesce a rilevarla meglio.'));resolve({latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy})},()=>reject(Error('Non riesco a leggere la tua posizione. Puoi continuare a consultare le segnalazioni.')),{enableHighAccuracy:true,timeout:12000,maximumAge:30000})})}
 function bindConfirmations(){document.querySelectorAll('[data-sky-locate-confirm]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{confirmationPosition=await currentPosition();confirmationPositionAt=Date.now();renderFeed();ctx.toast('Puoi confermare le segnalazioni entro 5 km dalla posizione rilevata.')}catch(e){ctx.toast(e.message)}finally{b.disabled=false}});document.querySelectorAll('[data-sky-confirm]').forEach(b=>b.onclick=e=>confirmReport(b.dataset.skyConfirm,e.isTrusted))}
 async function confirmReport(id,userGesture){if(confirming.has(id))return;const report=findReport(id);if(!report||!canConfirm(report))return;confirming.add(id);renderFeed();try{const position=await currentPosition();confirmationPosition=position;confirmationPositionAt=Date.now();if(skyDistance(position,report)>5)throw Error('Questa segnalazione è oltre 5 km dalla tua posizione.');await ctx.api('sky/session',{});const result=await ctx.api('sky/reports/'+encodeURIComponent(id)+'/confirm',{...position,consent:true});for(const rows of [data?.reports,data?.nearbyReports])for(const row of rows||[])if(row.id===id){row.confirms=result.confirms;row.confirmed=result.confirmed}try{if(userGesture&&!document.hidden&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&localStorage.getItem('ms-haptics')!=='false')navigator.vibrate?.(12)}catch{}ctx.toast(result.confirmed?'Conferma registrata.':'La segnalazione non è più disponibile.')}catch(e){ctx.toast(e.message)}finally{confirming.delete(id);renderFeed()}}

 function feedContent(){if(error&&!data)return `<p role="alert">${esc(error)}</p><button type="button" data-sky-retry>Riprova</button>`;if(!data)return '<div class="sky-feed-loading" data-ui-loading="true" aria-busy="true"><p role="status">Cerco le persone che raccontano il cielo…</p><div class="sky-loading-shape" aria-hidden="true"></div></div>';const selection=nearby(),rows=selection.rows,people=new Set(rows.map(r=>r.author)).size;
 if(selection.unavailable)return '<p role="status">Scegli una città per cercare le segnalazioni vicine.</p>';
 return `${error?`<p role="status">${esc(error)} · Ultimo aggiornamento delle ${time(data.asOf)}.</p>`:''}${rows.length?`${selection.radius>5?`<p>${incomplete()?'Nei dati caricati non trovo':'Non risultano'} segnalazioni entro 5 km da ${esc(ctx.get().place.name)} nelle ultime 2 ore.</p><p><strong>La più vicina${incomplete()?' fra quelle caricate':''}: ${esc(rows[0].city)}, circa ${distanceText(rows[0].distanceKm)}</strong> · ${esc(reportLabel(rows[0]))} · ${Math.floor((Date.now()-rows[0].created)/60000)} min fa.</p>`:''}<p>${people} ${people===1?'persona':'persone'} entro ${selection.radius} km · ultime 2 ore.${incomplete()?' Risultati parziali.':''}</p><p class="small">Distanze dalla posizione selezionata, calcolate sulle zone approssimate per privacy.</p><button type="button" class="sky-primary" data-sky-open>Racconta il cielo di ${esc(ctx.get().place.name)}</button><div class="sky-report-list">${rows.map(card).join('')}</div><p class="sky-privacy">Per confermare serve la posizione del dispositivo; non viene salvata nella conferma.</p><button type="button" data-sky-locate-confirm>Verifica la mia posizione per confermare</button>`:invitation()}`}

 function content(){return outbox()+feedContent()}
 function page(){return `<section class="sky-community"><p class="eyebrow">LE VOCI DELLA MAPPA</p><h1>Il cielo nella tua zona</h1><p>${esc(ctx.get().place.name)} · Adesso · ultime 2 ore</p>${grid()}<div id="sky-feed">${content()}</div><p id="sky-feedback" class="sky-success" aria-live="polite" ${feedbackText?'':'hidden'}>${esc(feedbackText)}</p><p><a href="#mappa">Guarda le persone sulla mappa →</a></p><p><a href="#pubblica">Scrivi un post più lungo</a></p><p><a href="#regole">Regole della community</a></p>${COMMUNITY_FEATURES.extraCommunity?`<details><summary>Altre funzioni della community</summary><a href="#archivio">Post e conversazioni precedenti</a><a href="#fitcheck">Consigli su come vestirti</a><a href="#sfide">Sfide delle città</a></details>`:''}</section>`}
 function bind(){bindConfirmations();bindQuick();document.querySelectorAll('[data-sky-open]').forEach(b=>b.onclick=open);document.querySelectorAll('[data-sky-retry],[data-living-retry]').forEach(b=>b.onclick=()=>load(true));document.querySelectorAll('[data-sky-zone]').forEach(b=>b.onclick=()=>{const r=findReport(b.dataset.skyZone);if(r)showZone(r)});if(active())load();clearInterval(timer);if(active())timer=setInterval(()=>{if(!document.hidden){expire();load(true);checkFeedback()}},30000);if(pending&&ctx.get().route==='mappa'){const r=pending;pending=null;setTimeout(()=>celebrate(r),300)}}
 function paint(){if(data)ctx.world.setData(data);renderFeed();ctx.world.refreshWeather()}
 function bindControls(){bindConfirmations();bindQuick();document.querySelectorAll('[data-sky-open]').forEach(b=>b.onclick=open);document.querySelectorAll('[data-sky-retry],[data-living-retry]').forEach(b=>b.onclick=()=>load(true));document.querySelectorAll('[data-sky-zone]').forEach(b=>b.onclick=()=>showZone(findReport(b.dataset.skyZone)))}
 async function load(force=false){if(loading||document.hidden||!active()||!force&&Date.now()-lastLoad<25000)return;loading=true;try{const locationKey=placeKey(),p=ctx.get().place,next=await ctx.api('sky/reports');if(next.truncated){try{const near=await ctx.api('sky/nearby?'+new URLSearchParams({lat:p.latitude,lon:p.longitude}));if(Array.isArray(near.reports)){next.nearbyReports=near.reports;next.nearbyTruncated=near.truncated;next.nearbyFor=locationKey}}catch{/* Partial global results remain explicitly labelled. */}}if(!Array.isArray(next.reports)||!Number.isInteger(next.stats?.people))throw Error('Risposta non valida.');if(data){const known=new Set(data.reports.map(r=>r.id)),near=next.reports.filter(r=>!r.own&&!known.has(r.id)&&skyDistance(p,r)<=3);if(near.length)try{navigator.setAppBadge?.(near.length)?.catch?.(()=>{})}catch{}}data=next;error='';lastLoad=Date.now();if(!feedbackAt&&!feedbackText&&data.reports.some(r=>r.own))feedbackAt=Date.now()+180000;paint()}catch(e){error=e.message;ctx.world.setError(error);renderFeed()}finally{loading=false}}
 function expire(){if(data){data.reports=data.reports.filter(r=>r.expires>Date.now());if(feedbackReport&&!data.reports.some(r=>r.id===feedbackReport)){feedbackText='';feedbackAt=0;feedbackReport='';const slot=$('#sky-feedback');if(slot){slot.textContent='';slot.hidden=true}}paint()}}
 function setSheet(){const dialog=$('#dialog');dialog.classList.add('sky-sheet');dialog.addEventListener('close',()=>dialog.classList.remove('sky-sheet'),{once:true})}
 async function open(){if(posting)return;const p=ctx.get().place;reportDraft={id:crypto.randomUUID(),latitude:p.latitude,longitude:p.longitude,city:p.name,consent:true,options:[],photo:''};ctx.modal('Racconta il tuo cielo',`<p>Stai raccontando <strong>${esc(p.name)}</strong>. Scegli solo il tempo che osservi lì adesso.</p><p class="sky-privacy">Toccando una scelta pubblichi il cielo e la zona approssimata per 2 ore. Nessun indirizzo preciso.</p><button type="button" class="sky-text" id="sky-change-city">Cambia città</button><div class="sky-choices">${SKY_LEVELS.map(([label,sub],i)=>`<button type="button" data-sky-level="${i}"><strong>${label}</strong><span>${sub}</span><span aria-hidden="true">→</span></button>`).join('')}</div><div class="sky-options" aria-label="Aggiungi un dettaglio facoltativo">${[['sun','☀ Sole'],['cloud','☁ Nuvole'],['wind','↗ Vento']].map(([id,label])=>`<button type="button" data-sky-option="${id}" aria-pressed="false">${label}</button>`).join('')}</div><label class="sky-photo-label">Aggiungi foto <input id="sky-photo" type="file" accept="image/*" capture="environment"></label><p id="sky-photo-status" role="status"></p><details class="sky-extra"><summary>Neve o grandine?</summary><div class="sky-options"><button type="button" data-sky-option="snow" aria-pressed="false">❄ Neve</button><button type="button" data-sky-option="hail" aria-pressed="false">● Grandine</button></div><p>La tua osservazione non è un’allerta ufficiale.</p></details><p id="sky-report-status" role="status">La prima segnalazione non richiede un account.</p>`,null);setSheet();$('#sky-change-city').onclick=()=>{$('#dialog').close();ctx.changeCity()};
 document.querySelectorAll('[data-sky-option]').forEach(b=>b.onclick=()=>{const k=b.dataset.skyOption,on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));reportDraft.options=on?[...reportDraft.options,k]:reportDraft.options.filter(x=>x!==k)});
 $('#sky-photo').onchange=async e=>{const input=e.target,file=input.files?.[0],draftToken=reportDraft;if(!file)return;draftToken.photo='';$('#sky-photo-status').textContent='Preparo la foto…';document.querySelectorAll('[data-sky-level]').forEach(b=>b.disabled=true);try{const photo=await fotoDataURL(file,1050000);if(reportDraft!==draftToken||!input.isConnected||input.files?.[0]!==file)return;reportDraft.photo=photo;$('#sky-photo-status').textContent='Foto pronta. Metadati EXIF e posizione GPS rimossi.'}catch(error){if(reportDraft===draftToken&&input.isConnected&&input.files?.[0]===file)$('#sky-photo-status').textContent=error.message+' Puoi segnalare senza foto.'}finally{if(reportDraft===draftToken&&input.isConnected&&input.files?.[0]===file)document.querySelectorAll('[data-sky-level]').forEach(b=>b.disabled=false)}};
 document.querySelectorAll('[data-sky-level]').forEach(b=>b.onclick=e=>submit(Number(b.dataset.skyLevel),e.isTrusted));
 }
 async function submit(level,userGesture=false){if(posting)return;posting=true;const buttons=[...document.querySelectorAll('[data-sky-level]')];buttons.forEach(b=>b.disabled=true);$('#sky-report-status').textContent='Accendo il tuo punto…';try{const result=await sendObservation({...reportDraft,observedAt:reportDraft.observedAt||(reportDraft.observedAt=Date.now()),name:displayName,level});if(result.queued){$('#dialog').close();reportDraft=null;ctx.toast('Verrà inviata appena torni online.');return}reportHaptic('success',userGesture);data=data||{reports:[],stats:result.stats,asOf:Date.now()};data.reports=[result.report,...data.reports.filter(r=>r.id!==result.report.id)];if(data.nearbyReports)data.nearbyReports=[result.report,...data.nearbyReports.filter(r=>r.id!==result.report.id)];data.stats=result.stats;data.asOf=Date.now();error='';paint();$('#dialog').close();feedbackAt=Date.now()+180000;feedbackReport=result.report.id;feedbackText='';reportDraft=null;if(ctx.get().route!=='mappa'){pending=result.report;location.hash='mappa'}else celebrate(result.report)}catch(e){reportHaptic('error',userGesture);if($('#sky-report-status'))$('#sky-report-status').textContent=e.message}finally{posting=false;buttons.forEach(b=>b.disabled=false)} }
 function celebrate(report){ctx.world.celebrate(report);const slot=$('#living-feedback');if(!slot)return;slot.innerHTML=`<div class="sky-success" role="status"><h2>${report.visibility==='only-you'?'Il tuo punto è visibile a te.':'Sei sul pianeta.'}</h2><p>${report.visibility==='only-you'?'Questa segnalazione non compare nella vista pubblica.':`Insieme a te, ${data.stats.people} ${data.stats.people===1?'persona racconta':'persone raccontano'} il cielo in questo momento.`}</p><button type="button" id="sky-save-card">Salva l’immagine</button><button type="button" id="sky-open-own">La tua segnalazione</button></div>`;$('#sky-save-card').onclick=()=>saveCard(report);$('#sky-open-own').onclick=()=>showZone(report);ctx.toast('Il tuo cielo è stato salvato.');}
 async function saveCard(report){const button=$('#sky-save-card');if(button?.disabled)return;try{if(button){button.disabled=true;button.textContent='Preparo l’immagine…'}const scene=ctx.world.scene();if(!scene){ctx.toast('Il globo sta ancora caricando. Riprova tra poco.');return}const view=scene.capture(),canvas=document.createElement('canvas');canvas.width=canvas.height=1080;const x=canvas.getContext('2d'),bg=x.createLinearGradient(0,0,0,1080);bg.addColorStop(0,'#10243a');bg.addColorStop(1,'#070e1c');x.fillStyle=bg;x.fillRect(0,0,1080,1080);const ratio=Math.min(1080/view.width,740/view.height),w=view.width*ratio,h=view.height*ratio;x.drawImage(view,(1080-w)/2,170+(740-h)/2,w,h);x.fillStyle='#ffb777';x.font='700 52px system-ui';x.fillText('Sei sul pianeta.',64,100,952);x.fillStyle='#f2f7fc';x.font='700 42px system-ui';x.fillText(report.city,64,160,952);x.font='500 30px system-ui';x.fillText(reportLabel(report)+' · '+time(report.created),64,942,952);x.font='400 24px system-ui';x.fillText('MeteoSocial · Il cielo raccontato dalle persone',64,1000,952);x.font='400 18px system-ui';x.fillText(location.host,64,1038,952);const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error('Immagine non disponibile.')),'image/png'));const url=URL.createObjectURL(blob);ctx.modal('Il tuo cielo da condividere',`<img src="${url}" width="1080" height="1080" style="display:block;width:100%;height:auto" alt="La tua card MeteoSocial: ${esc(report.city)}"><p><a class="button" id="sky-download-card" href="${url}" download="meteosocial-il-mio-cielo.png">Scarica PNG</a></p><p>Se il download non parte, tieni premuta l’immagine sul telefono per salvarla.</p>`,null);$('#dialog').addEventListener('close',()=>setTimeout(()=>URL.revokeObjectURL(url),30000),{once:true});$('#sky-download-card').click()}catch{ctx.toast('Non riesco a preparare l’immagine. Riprova dal globo.')}finally{if(button){button.disabled=false;button.textContent='Salva l’immagine'}}}

 async function showZone(point){if(!point)return;const seq=++zoneRun,name=point.city||point.name||'Questa zona';ctx.modal(name,'<p role="status">Ascolto le persone e consulto il modello…</p>',null);setSheet();const target=$('#dialog-body');const requests=await Promise.allSettled([ctx.api('sky/zone?'+new URLSearchParams({lat:point.latitude,lon:point.longitude})),fetch('https://api.open-meteo.com/v1/forecast?'+new URLSearchParams({latitude:point.latitude,longitude:point.longitude,current:'temperature_2m,weather_code,precipitation,wind_speed_10m',timezone:'auto'}),{signal:AbortSignal.timeout(12000)}).then(async r=>{if(!r.ok)throw Error();return r.json()})]);if(seq!==zoneRun||!$('#dialog').open||target!==$('#dialog-body'))return;
 const zone=requests[0].status==='fulfilled'?requests[0].value:null,model=requests[1].status==='fulfilled'?requests[1].value:null,c=model?.current,rows=zone?.reports||[],current=rows.find(r=>r.id===point.id)||rows[0],kind=c?weatherKind(c.weather_code):null,peopleWet=zone?.level>0,modelWet=['rain','snow','storm'].includes(kind)||c?.precipitation>0,mismatch=zone?.level!=null&&zone?.people>0&&c&&peopleWet!==modelWet;
 target.innerHTML=`<section class="sky-people-summary"><p class="eyebrow">COSA DICONO LE PERSONE</p><h2>${zone?.people?`${zone.people} ${zone.people===1?'persona ha segnalato':'persone hanno segnalato'}. Sintesi: ${esc((zone.summary||[]).join(', ')||'contributi diversi')}`:zone?'Qui il pianeta aspetta una voce.':'Le segnalazioni non sono disponibili.'}</h2><p>${zone?.people?`Entro 3 km · ultima segnalazione alle ${time(rows[0].created)}. Sintesi pesata dei contributi, non una misura certificata.`:'Racconta quello che vedi per accendere la zona.'}</p>${current?.photo?`<img class="sky-zone-photo" src="/api/sky/photo/${encodeURIComponent(current.id)}" alt="Il cielo di ${esc(current.city)}">`:''}</section><section class="sky-model-summary"><p class="eyebrow">COSA DICE IL MODELLO</p><h2>${c?`${valueText(c.temperature_2m,'°')} · ${esc(weatherName(c.weather_code))}`:'Il modello non è disponibile.'}</h2><p>${c?`Vento ${valueText(c.wind_speed_10m,' km/h')} · Precipitazioni ${valueText(c.precipitation,' mm',1)}<br>Open-Meteo · ${esc(c.time)} · ${esc(model.timezone)}`:'Riprova tra poco. Le osservazioni delle persone restano distinte.'}</p></section>${mismatch?`<p class="sky-disagreement"><strong>Il modello dice ${esc(weatherName(c.weather_code).toLowerCase())}. Le persone dicono ${esc(zone.level==null?[...new Set(rows.map(reportLabel))].join(', '):SKY_LEVELS[zone.level][0].toLowerCase())}.</strong><br>Orari, precisione e zone possono differire: mostriamo entrambe le voci.</p>`:''}<section class="sky-fit"><h3>Come vestirti qui</h3><p>${c?(c.temperature_2m<12?'Porta uno strato caldo.':c.temperature_2m>27?'Vestiti leggeri e acqua con te.':'Uno strato leggero in più può essere utile.')+(peopleWet||modelWet?' Tieni un ombrello a portata di mano.':''): 'Consulta le previsioni prima di uscire.'}</p><a href="#fitcheck" data-close-sheet>Apri Fit Check</a></section><section><h3>Illumina ${esc(name)}</h3><p>${zone?.people||0} ${zone?.people===1?'persona':'persone'} entro 3 km · obiettivo della zona: 10 voci indipendenti.</p><progress max="10" value="${Math.min(10,zone?.people||0)}" aria-label="Persone che illuminano la zona"></progress></section>${rows.length?`<details><summary>Le osservazioni (${rows.length})</summary>${rows.map(r=>`<div class="sky-observation"><p>${esc(r.name||'Una persona')}${professionLabel(r.mestiere)}</p><strong>${esc(reportLabel(r))} · ${time(r.created)} · ${Math.max(0,Math.floor((Date.now()-r.created)/60000))} min fa${Number.isFinite(r.distanceKm)?' · circa '+distanceText(r.distanceKm):''}${r.own?' · Tu':''}</strong>${r.options.length?`<p>${r.options.map(o=>({sun:'Sole',cloud:'Nuvole',wind:'Vento',hail:'Grandine',snow:'Neve'}[o])).join(' · ')}</p>`:''}<div>${r.own?`<button type="button" data-sky-delete="${r.id}">Elimina</button>`:`<button type="button" data-sky-block="${esc(r.author)}">Blocca persona</button><button type="button" data-sky-flag="${r.id}">Segnala abuso</button>`}</div></div>`).join('')}</details>`:''}<button type="button" class="sky-primary" id="sky-zone-report">Racconta il tuo cielo</button><p class="sky-privacy">Le segnalazioni scadono dopo 2 ore. I contenuti segnalati per abuso vengono oscurati dalla vista pubblica.</p>`;
 $('#sky-zone-report').onclick=()=>{$('#dialog').close();open()};target.querySelector('[data-close-sheet]').onclick=()=>$('#dialog').close();
 target.querySelectorAll('[data-sky-delete]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await ctx.api('sky/delete',{id:b.dataset.skyDelete});$('#dialog').close();await load(true);ctx.toast('Segnalazione eliminata.')}catch(e){ctx.toast(e.message);b.disabled=false}});
 target.querySelectorAll('[data-sky-block]').forEach(b=>b.onclick=async()=>{try{await ctx.api('sky/session',{});await ctx.api('sky/block',{target:b.dataset.skyBlock});$('#dialog').close();await load(true);ctx.toast('Persona bloccata.')}catch(e){ctx.toast(e.message)}});
 target.querySelectorAll('[data-sky-flag]').forEach(b=>b.onclick=()=>{const id=b.dataset.skyFlag;ctx.modal('Segnala abuso','<label>Motivo<select id="sky-reason"><option>Contenuto offensivo o pericoloso</option><option>Dati personali</option><option>Spam o informazioni ingannevoli</option></select></label><p>Il contenuto verrà oscurato e la persona bloccata per te.</p>',async()=>{await ctx.api('sky/session',{});await ctx.api('sky/flag',{id,reason:$('#sky-reason').value});await load(true);ctx.toast('Contenuto oscurato e persona bloccata.')});setSheet()});
 }
 async function checkFeedback(){if(!feedbackAt||Date.now()<feedbackAt)return;feedbackAt=Date.now()+120000;const own=data?.reports.find(r=>r.own&&r.expires>Date.now()&&(!feedbackReport||r.id===feedbackReport));if(!own){feedbackAt=0;return}try{
 const zone=await ctx.api('sky/zone?'+new URLSearchParams({lat:own.latitude,lon:own.longitude})),fresh=zone.reports.find(r=>r.id===own.id);if(!fresh||fresh.visibility==='only-you')return;
 const others=agreeingPeople(fresh,zone.reports),confirmations=fresh.confirms||0;if(!others&&!confirmations)return;
 let modelText='Il modello non è disponibile adesso.';try{const response=await fetch('https://api.open-meteo.com/v1/forecast?'+new URLSearchParams({latitude:own.latitude,longitude:own.longitude,current:'weather_code',timeformat:'unixtime'}),{signal:AbortSignal.timeout(12000)});if(response.ok){const model=await response.json(),c=model.current;if(Number.isFinite(c?.weather_code)&&Number.isFinite(c.time)&&Math.abs(Date.now()/1000-c.time)<1800)modelText='Il modello indica '+weatherName(c.weather_code).toLowerCase()+' (dato delle '+time(c.time*1000)+').' }}catch{}
 if(!active()||!data?.reports.some(r=>r.id===own.id&&r.expires>Date.now()))return;
 feedbackReport=own.id;feedbackText=modelText+' '+(others?(others===1?'Tu e un’altra persona':'Tu e altre '+others+' persone')+' entro 3 km segnalate '+reportLabel(own).toLowerCase()+'.':'La tua segnalazione di '+reportLabel(own).toLowerCase()+' è stata confermata da '+confirmations+' '+(confirmations===1?'persona':'persone')+' entro 5 km.')+' Segnalazione delle '+time(own.created)+'. Le osservazioni aggiungono informazioni locali; il modello resta distinto.';
 let slot=$('#sky-feedback');if(!slot&&$('#living-feedback')){slot=document.createElement('p');slot.id='sky-feedback';slot.className='sky-success';slot.setAttribute('aria-live','polite');$('#living-feedback').append(slot)}if(slot){slot.hidden=false;slot.textContent=feedbackText}feedbackAt=0;
 }catch{}}

 window.addEventListener('sky-published',()=>load(true));
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&active())load(true)});
 return {panel:()=>`<details class="community-live"><summary>Dal posto · segnalazioni nelle ultime 2 ore</summary><p>Osservazioni vicine alla località selezionata, fino a 150 km. Sono racconti delle persone, non allerte ufficiali.</p>${grid()}<div id="sky-feed">${content()}</div><p id="sky-feedback" class="sky-success" aria-live="polite" ${feedbackText?'':'hidden'}>${esc(feedbackText)}</p><a href="#mappa">Esplora le segnalazioni sulla mappa</a></details>`,page,bind,open,quick,profileHTML,bindProfile,showZone,load,refresh(){renderFeed()},stop(){clearInterval(timer);timer=0;feedMotion?.stop()},data:()=>data};
}
